contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with all test logic
    function run(uint256 flag) public payable {
        // No precondition required
        // Attempt the potentially-destructive call and record whether it reverted
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After the call: either it reverted, or C's balance is zero
        assert(reverted || address(c).balance == 0);
    }

    // allow receiving Ether from selfdestruct if needed
    receive() external payable {}
}

